SourceCode.Declaration:
/// <summary>
/// Controller class for order total recalculation SysOperation.
/// </summary>
internal final class SOrderRecalculateController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Initializes the controller with synchronous execution mode.
/// </summary>
protected void new()
{
    super(
        classStr(SOrderRecalculateService),
        methodStr(SOrderRecalculateService, process),
        SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Main entry point for the recalculation operation.
/// </summary>
/// <param name="_args">Standard form arguments.</param>
public static void main(Args _args)
{
    SOrderRecalculateController controller;
    controller = new SOrderRecalculateController();
    controller.parmArgs(_args);
    controller.startOperation();
}
